insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('6e14c5bc-7bf4-4dfd-8f6c-426a9ad36c80', '113b8fde-81f0-4837-91b2-4686b856f1a9', $$f(x) = ½x³ − 4x snijdt de x-as in M, O(0,0) en N; figuur 1$$,
   $$wiskunde-b-havo-2017-ii-afstand-tussen-twee-raaklijnen-context1.png$$,
   $$De functie f is gegeven door f(x) = ½x³ − 4x. De grafiek van f snijdt de x-as achtereenvolgens in M, de oorsprong O(0,0) en N. Zie figuur 1.
figuur 1: de grafiek van f met de punten M, O en N$$, 'inline'),
  ('446cea60-2e20-4836-95ee-950e7c6fb9fc', '113b8fde-81f0-4837-91b2-4686b856f1a9', $$k en l evenwijdige raaklijnen aan f; k raakt in A(−2, 4); figuur 2; afstand van O tot k is de helft van de afstand tussen k en l$$,
   $$wiskunde-b-havo-2017-ii-afstand-tussen-twee-raaklijnen-context2.png$$,
   $$De lijnen k en l zijn evenwijdige raaklijnen aan de grafiek van f. Lijn k raakt de grafiek van f in het punt A(−2,4). Zie figuur 2.
figuur 2: de grafiek van f met de evenwijdige raaklijnen k (in A) en l
De afstand van O tot k is de helft van de afstand tussen k en l.$$, 'inline'),
  ('62b4233c-2c68-4058-b37d-44227d2c5c1d', '5ce0506d-bd80-4e3d-be50-eccc0cd6e6fa', $$cirkel c: x² + (y − 5)² = 25 met middelpunt M(0,5); C(−4,8) en D(4,8) op c; raaklijnen k in C en l in D snijden de x-as in A en B; figuur 1; B = (10,0)$$,
   $$wiskunde-b-havo-2017-ii-over-een-cirkel-gespannen-context1.png$$,
   $$De cirkel c met middelpunt M(0,5) is gegeven door x² + (y − 5)² = 25. De punten C(−4,8) en D(4,8) liggen op de cirkel. De lijn k is de raaklijn aan c in punt C en de lijn l is de raaklijn aan c in punt D. Punt A is het snijpunt van k met de x-as en punt B is het snijpunt van l met de x-as. Zie figuur 1.
figuur 1: de cirkel c met de raaklijnen k en l en de punten A, B, C, D en M
De coördinaten van punt B zijn (10,0).$$, 'inline'),
  ('dfbcf84e-5b1d-47f3-8d84-ca7e5412c20f', '5ce0506d-bd80-4e3d-be50-eccc0cd6e6fa', $$touwtje van A naar B over de cirkel: recht van A naar C en van D naar B, over de cirkel tussen C en D; figuur 2$$,
   $$wiskunde-b-havo-2017-ii-over-een-cirkel-gespannen-context2.png$$,
   $$Tussen A en B wordt denkbeeldig een touwtje gespannen dat over de cirkel heen gaat. Het touwtje is zo gespannen dat het tussen C en D precies over de cirkel ligt. Het touwtje is recht tussen A en C en tussen D en B. Zie figuur 2.
figuur 2: het touwtje (dik getekend) van A via C en D naar B$$, 'inline'),
  ('e00b01c7-460f-44f4-9fdd-444c90b1c4e2', 'ef8b18fe-af6f-412b-8a8c-73c743bd6f50', $$prijs van elektriciteit stijgt niet elk jaar met hetzelfde percentage; tabel met jaarlijkse prijsstijging 1997-2006; prijs in 10 jaar ongeveer verdubbeld; verdubbeling ook met vast jaarlijks percentage$$,
   $$wiskunde-b-havo-2017-ii-zonnepanelen-context1.png$$,
   $$De prijs van elektrische energie - gewoonlijk elektriciteit genoemd - stijgt niet elk jaar met hetzelfde percentage.
In de tabel staan de groeipercentages ten opzichte van het voorafgaande jaar voor de periode van 1997 tot en met 2006.
Uit de gegevens in de tabel volgt dat de prijs van elektriciteit in 10 jaar tijd ongeveer is verdubbeld.
Een verdubbeling in 10 jaar kan ook bereikt worden door de prijs van elektriciteit jaarlijks met een vast percentage te laten stijgen.
Met zonnepanelen kan worden bespaard op de elektriciteitskosten.
Hoeveel er met zonnepanelen kan worden bespaard, hangt in deze opgave alleen af van de prijsstijging van elektriciteit en van de elektriciteitsopbrengst van de zonnepanelen.
tabel: prijsstijging ten opzichte van het voorafgaande jaar in gehele procenten
1996: − 1997: 2
1998: 1
1999: 7
2000: 14
2001: 26
2002: 3
2003: 3
2004: 5
2005: 8
2006: 6$$, 'inline'),
  ('d17ce9fd-2bb3-44a7-bc31-c7ef05d830a7', 'ef8b18fe-af6f-412b-8a8c-73c743bd6f50', $$totale besparing B = (19,9V/P)·((1 + P/100)ᵗ − 1); zonnepanelen januari 2006, kosten €13000, 2250 kWh per jaar, prijsstijging 7% per jaar$$,
   $$wiskunde-b-havo-2017-ii-zonnepanelen-context2.png$$,
   $$Zonder rekening te houden met de kosten van aankoop en installatie kan de totale besparing vanaf het moment van installatie worden berekend met behulp van de volgende formule:
B = (19,9V / P) · ((1 + P/100)ᵗ − 1)
Hierin is B de totale besparing in euro''s, V de elektriciteitsopbrengst van de zonnepanelen in kWh per jaar, P het percentage waarmee de elektriciteitsprijs jaarlijks stijgt en t het aantal jaren na 2006.
In januari 2006 worden zonnepanelen geplaatst.
De kosten voor de aankoop en installatie hiervan zijn €13000,−.
De zonnepanelen leveren 2250 kWh per jaar.
We nemen aan dat de elektriciteitsprijs jaarlijks steeds met 7% stijgt.
Na een aantal jaren zal de totale besparing groter zijn dan de aanschafprijs van de zonnepanelen.$$, 'inline'),
  ('0b2ffd96-374c-4832-ab8c-bf1ff2a836a5', 'ef8b18fe-af6f-412b-8a8c-73c743bd6f50', $$school: opbrengst 2011 in totaal 45000 kWh, waarvan 520 kWh in december; toenamediagram eerste halfjaar 2012; ⚠️ CONTROLEREN: bron drukt '20125000 kWh minder' af (vermoedelijk 2012: 5000 kWh minder dan in 2011)$$,
   $$wiskunde-b-havo-2017-ii-zonnepanelen-context3.png$$,
   $$Een school heeft een grote hoeveelheid zonnepanelen op het dak staan. In het jaar 2011 was de elektriciteitsopbrengst van deze zonnepanelen in totaal 45000 kWh, waarvan 520 kWh in de maand december.
In het toenamediagram in de figuur zijn de gegevens van het eerste halfjaar van 2012 verwerkt.
figuur: toenamediagram van de elektriciteitsopbrengst (in kWh) per maand, met waarden voor januari tot en met juni
Uiteindelijk bleek dat in het jaar 20125000 kWh minder elektriciteit werd geproduceerd dan in 2011. ⚠️ CONTROLEREN: de bron-PDF drukt ''20125000'' af; bedoeld is vermoedelijk ''in het jaar 2012 5000 kWh minder''.$$, 'inline'),
  ('6b2aecd3-e3c7-4bba-9fee-cc0aa3cf5324', '3835bc91-2820-4bfa-b7e3-bb3294ac3ec2', $$f(x) = (2x² + 18)/(3x); toppen A en B; figuur$$,
   $$wiskunde-b-havo-2017-ii-de-toppen-van-de-grafiek-van-een-gebroken-functie-context1.png$$,
   $$De functie f is gegeven door: f(x) = (2x² + 18)/(3x)
De punten A en B zijn de toppen van de grafiek van f. Zie de figuur.
figuur: de grafiek van f met de toppen A en B$$, 'inline'),
  ('ee8e9bec-71bc-48e1-9b45-61513f46e6d0', '0f34c51f-70c3-456d-90ac-2a5720804e9f', $$f(x) = 1 − 2sin(πx) op [0, 2]$$,
   $$wiskunde-b-havo-2017-ii-sinus-en-wortel-context1.png$$,
   $$Op het domein [0,2] is de functie f gegeven door: f(x) = 1 − 2sin(πx)$$, 'inline'),
  ('a97ff620-ef7a-4c09-8f7d-9da3c98a85fc', '0f34c51f-70c3-456d-90ac-2a5720804e9f', $$g(x) = −1 + √(16x − 8); figuur; P en Q zijn de toppen van f$$,
   $$wiskunde-b-havo-2017-ii-sinus-en-wortel-context2.png$$,
   $$Verder is gegeven de functie g door g(x) = −1 + √(16x − 8).
Zie de figuur.
figuur: de grafieken van f en g met de toppen P en Q van f
De punten P en Q zijn de toppen van de grafiek van f.$$, 'inline'),
  ('199bdc58-3ed5-4669-95e6-746c082f33b3', 'cce39413-81b5-4084-b93b-6754e3b9dcd8', $$gestapelde tegels met overhang; foto; maximale overhang M bij n tegels: tegel t steekt 1/(2t) tegellengte uit ten opzichte van tegel t + 1; figuur$$,
   $$wiskunde-b-havo-2017-ii-tegels-stapelen-context1.png$$,
   $$Door gelijke rechthoekige tegels ''netjes'' op elkaar te stapelen kan een toren gebouwd worden die naar één kant overhelt. Zie de foto.
foto: een stapel tegels die naar één kant overhelt
Het uitsteken van de gestapelde tegels vanaf de onderste tegel wordt de overhang genoemd. De overhang is maximaal als de stapel tegels nog net in evenwicht is, dus net niet omvalt.
De maximale overhang M bij een stapel van n tegels ontstaat als volgt: − laat tegel 1 (de bovenste tegel) een halve tegellengte uitsteken ten opzichte van tegel 2 (de eronder liggende tegel); − laat tegel 2 een kwart uitsteken ten opzichte van tegel 3; − laat tegel 3 een zesde uitsteken ten opzichte van tegel 4 − enzovoort.
Algemeen geldt dan: tegel t steekt 1/(2t)-deel van een tegellengte uit ten opzichte van tegel t + 1. Zie de figuur.
figuur: tegel 1 tot en met tegel n gestapeld met uitstekende delen ½, ¼, 1/6, ..., 1/(2t) en de maximale overhang M$$, 'inline'),
  ('df16cfcf-0687-469a-b424-f33bc79df6dd', 'cce39413-81b5-4084-b93b-6754e3b9dcd8', $$tegels van 30 cm lang, 15 cm breed en 3 cm dik; M = 34,54·log(n − 1) + 8,658 + 15/(2(n − 1)) + 5/(4(n − 1)²) (1), n ≥ 2; overhang van 1 meter$$,
   $$wiskunde-b-havo-2017-ii-tegels-stapelen-context2.png$$,
   $$In de rest van deze opgave nemen we tegels van 30 cm lang en 15 cm breed met een dikte van 3 cm. Deze tegels stapelen we weer ''netjes'' op elkaar, zoals op de foto en in de figuur.
Bij deze tegels kan de maximale overhang M benaderd worden met de formule:
M = 34,54 · log(n − 1) + 8,658 + 15/(2(n − 1)) + 5/(4(n − 1)²) (1)
Hierin is M de maximale overhang in cm en is n het totaal aantal tegels in de stapel, met n ≥ 2.
Wanneer er voldoende tegels beschikbaar zijn, kan in theorie de maximale overhang zo groot worden gemaakt als gewenst.
Met de genoemde 3 cm dikke tegels wordt een overhang van 1 meter gemaakt.$$, 'inline'),
  ('f3d8ae7e-1c12-45bb-9712-cf22b4fa4581', 'cce39413-81b5-4084-b93b-6754e3b9dcd8', $$voor grote n: M = 34,54·log(n − 1) + 8,658 (2)$$,
   $$wiskunde-b-havo-2017-ii-tegels-stapelen-context3.png$$,
   $$Voor grote waarden van n kan M benaderd worden met de formule:
M = 34,54 · log(n − 1) + 8,658 (2)
Hierin is M weer de maximale overhang in cm en is n weer het totaal aantal tegels in de stapel.$$, 'inline'),
  ('6034b7d8-abef-4205-bbca-e5948558e8d5', 'b9ee1204-bf08-427e-a7d8-c8e9930d6dfc', $$baan van Pluto om de zon: perihelium en aphelium op de x-as, zon in de oorsprong; figuur 1; bovenste helft van de baan: y = √(1500 − 15/16·(x − 10)²) (1), x en y in AE; perihelium 30 AE en aphelium 50 AE$$,
   $$wiskunde-b-havo-2017-ii-pluto-context1.png$$,
   $$De dwergplaneet Pluto beweegt om de zon. De afstand van Pluto tot de zon is niet altijd even groot.
De plaats waar Pluto zich het dichtst bij de zon bevindt wordt het perihelium genoemd, de plaats waar Pluto zich het verst van de zon af bevindt het aphelium. De baan van Pluto wordt in een assenstelsel weergegeven met de zon in de oorsprong en het perihelium en het aphelium op de x-as.
In figuur 1 is een mogelijke positie van Pluto (P) weergegeven.
figuur 1: de baan van Pluto met de zon in de oorsprong, het perihelium, het aphelium en P(x,y)
Bij de bovenste helft van deze baan in het assenstelsel hoort (bij benadering) de volgende formule:
y = √(1500 − (15/16)(x − 10)²) (1)
Hierbij zijn x en y in astronomische eenheden AE (1 AE = 150 miljoen km).
Uit formule (1) volgt dat de afstand van Pluto tot de zon in het perihelium 30 AE is en in het aphelium 50 AE.$$, 'inline'),
  ('c5328573-f559-4aa6-a1c1-e40343461291', 'b9ee1204-bf08-427e-a7d8-c8e9930d6dfc', $$ander model: r = 37,5/(1 + 0,25·cos(α)) (2), r afstand tot de zon in AE, α hoek tussen zon-Pluto en zon-perihelium; figuur 2$$,
   $$wiskunde-b-havo-2017-ii-pluto-context2.png$$,
   $$Een ander model voor de afstand van Pluto tot de zon luidt:
r = 37,5 / (1 + 0,25 · cos(α)) (2)
Hierin is r de afstand van Pluto tot de zon in AE en is α de hoek tussen het lijnstuk zon-Pluto en het lijnstuk zon-perihelium. Zie figuur 2.
figuur 2: de baan van Pluto met de afstand r en de hoek α bij de zon$$, 'inline'),
  ('c3006e79-a680-45d5-8a4e-6f5686c525d2', 'c4be8f4f-84ed-43cb-a6d0-670b093417d5', $$cirkel c: (x + 4)² + (y − 5)² = 49 met middelpunt R en cirkel d: (x − 14)² + (y − 8)² = 16 met middelpunt S; cirkel e met middelpunt T(p, 0) raakt beide; figuur; RT = √(p² + 8p + 41)$$,
   $$wiskunde-b-havo-2017-ii-rakende-cirkels-context1.png$$,
   $$De cirkel c met middelpunt R is gegeven door (x + 4)² + (y − 5)² = 49 en de cirkel d met middelpunt S is gegeven door (x − 14)² + (y − 8)² = 16.
Een derde cirkel e, met middelpunt T op de x-as, raakt aan beide cirkels. Verder liggen c en d buiten e. Zie de figuur.
figuur: de cirkels c, d en e met de middelpunten R, S en T
De x-coördinaat van T noemen we p, dus OT = p.
Er geldt: de afstand van R tot T is gelijk aan √(p² + 8p + 41).$$, 'inline'),
  ('e76f250c-ab48-465e-ab6a-359393db667e', 'c4be8f4f-84ed-43cb-a6d0-670b093417d5', $$lijn RT gaat door het raakpunt van c en e, lijn ST door het raakpunt van d en e; ST = √(p² − 28p + 260)$$,
   $$wiskunde-b-havo-2017-ii-rakende-cirkels-context2.png$$,
   $$De lijn door R en T gaat door het raakpunt van de cirkels c en e.
Bovendien gaat de lijn door S en T door het raakpunt van de cirkels d en e.
Verder is de afstand van S tot T gelijk aan √(p² − 28p + 260).$$, 'inline');

