   $$wiskunde-b-havo-2017-ii-over-een-cirkel-gespannen-vraag4.png$$, $$5p 4 Bereken in één decimaal nauwkeurig de lengte van het touwtje.$$, array['62b4233c-2c68-4058-b37d-44227d2c5c1d', 'dfbcf84e-5b1d-47f3-8d84-ca7e5412c20f']::uuid[]),
