   $$wiskunde-b-havo-2017-ii-zonnepanelen-vraag6.png$$, $$4p 6 Bereken op algebraïsche wijze dit percentage. Rond je eindantwoord af op één decimaal.$$, array['e00b01c7-460f-44f4-9fdd-444c90b1c4e2']::uuid[]),
